  1→"use client";
  2→
  3→import { useState, useEffect, useCallback, useRef } from "react";
  4→
  5→interface JourneyStatusData {
  6→  journey_id: string;
  7→  state: "running" | "paused" | "completed" | "error" | "not_found";
  8→  elapsed_hours: number;
  9→  total_hours: number;
 10→  domains_completed: number;
 11→  total_domains: number;
 12→  hypotheses_completed: number;
 13→  total_hypotheses: number;
 14→  current_domain: string;
 15→  current_hypothesis: string;
 16→  gpu_temp: number;
 17→  cpu_temp: number;
 18→  tdp_consumed_percent: number;
 19→  thermal_events: number;
 20→  total_paused_minutes: number;
 21→  coherence: number;
 22→}
 23→
 24→interface UseJourneyStatusOptions {
 25→  journeyId?: string;
 26→  pollIntervalMs?: number;
 27→  enableSSE?: boolean;
 28→}
 29→
 30→const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8080";
 31→
 32→/**
 33→ * Hook for real-time journey status monitoring.
 34→ * 
 35→ * Supports both polling and SSE (Server-Sent Events) for live updates.
 36→ * Falls back to polling if SSE is not available.
 37→ * 
 38→ * Usage:
 39→ *   const { data, isLoading, error, refetch } = useJourneyStatus({
 40→ *     journeyId: "8hr_12345",
 41→ *     pollIntervalMs: 5000,
 42→ *   });
 43→ */
 44→export function useJourneyStatus({
 45→  journeyId = "8hr_current",
 46→  pollIntervalMs = 5000,
 47→  enableSSE = true,
 48→}: UseJourneyStatusOptions = {}) {
 49→  const [data, setData] = useState<JourneyStatusData | null>(null);
 50→  const [isLoading, setIsLoading] = useState(false);
 51→  const [error, setError] = useState<string | null>(null);
 52→  const [isConnected, setIsConnected] = useState(false);
 53→  
 54→  const eventSourceRef = useRef<EventSource | null>(null);
 55→  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null);
 56→
 57→  const fetchStatus = useCallback(async () => {
 58→    try {
 59→      const response = await fetch(`${API_BASE}/api/journey/status/${journeyId}`);
 60→      if (!response.ok) {
 61→        throw new Error(`HTTP ${response.status}`);
 62→      }
 63→      const status = await response.json();
 64→      
 65→      if (status.exists) {
 66→        setData({
 67→          journey_id: status.journey_id,
 68→          state: status.state.toLowerCase(),
 69→          elapsed_hours: 0, // Calculate from timestamps
 70→          total_hours: 8,
 71→          domains_completed: status.hypotheses_completed / 5, // Approximate
 72→          total_domains: 4,
 73→          hypotheses_completed: status.hypotheses_completed,
 74→          total_hypotheses: status.total_hypotheses,
 75→          current_domain: status.phase?.split("_")[0] ?? "unknown",
 76→          current_hypothesis: status.phase ?? "Starting...",
 77→          gpu_temp: status.gpu_temp ?? 0,
 78→          cpu_temp: status.cpu_temp ?? 0,
 79→          tdp_consumed_percent: 0, // Not yet available
 80→          thermal_events: 0,
 81→          total_paused_minutes: 0,
 82→          coherence: 0.5,
 83→        });
 84→      } else {
 85→        // No active journey
 86→        setData(null);
 87→      }
 88→      setError(null);
 89→    } catch (err) {
 90→      setError(err instanceof Error ? err.message : "Unknown error");
 91→      // Keep previous data if available
 92→    }
 93→  }, [journeyId]);
 94→
 95→  // Setup SSE connection
 96→  useEffect(() => {
 97→    if (!enableSSE) return;
 98→
 99→    const connectSSE = () => {
100→      try {
101→        const eventSource = new EventSource(
102→          `${API_BASE}/api/journey/stream/${journeyId}`
103→        );
104→
105→        eventSource.onopen = () => {
106→          setIsConnected(true);
107→          setError(null);
108→        };
109→
110→        eventSource.onmessage = (event) => {
111→          try {
112→            const status = JSON.parse(event.data);
113→            
114→            if (status.error) {
115→              setError(status.error);
116→              return;
117→            }
118→
119→            if (status.exists) {
120→              setData({
121→                journey_id: status.journey_id,
122→                state: status.state?.toLowerCase() ?? "unknown",
123→                elapsed_hours: ((Date.now() / 1000 - status.last_updated) / 3600),
124→                total_hours: 8,
125→                domains_completed: Math.floor(status.hypotheses_completed / 5),
126→                total_domains: 4,
127→                hypotheses_completed: status.hypotheses_completed,
128→                total_hypotheses: status.total_hypotheses,
129→                current_domain: status.phase?.split("_")[0] ?? "unknown",
130→                current_hypothesis: status.phase ?? "Initializing...",
131→                gpu_temp: status.gpu_temp ?? 0,
132→                cpu_temp: status.cpu_temp ?? 0,
133→                tdp_consumed_percent: status.progress?.tdp_percent ?? 0,
134→                thermal_events: status.progress?.thermal_events ?? 0,
135→                total_paused_minutes: status.progress?.paused_minutes ?? 0,
136→                coherence: status.progress?.coherence ?? 0.5,
137→              });
138→            }
139→          } catch (err) {
140→            console.error("Failed to parse SSE data:", err);
141→          }
142→        };
143→
144→        eventSource.onerror = () => {
145→          setIsConnected(false);
146→          setError("SSE connection error - falling back to polling");
147→          eventSource.close();
148→          
149→          // Fall back to polling
150→          if (pollIntervalRef.current) {
151→            clearInterval(pollIntervalRef.current);
152→          }
153→          pollIntervalRef.current = setInterval(fetchStatus, pollIntervalMs);
154→        };
155→
156→        eventSourceRef.current = eventSource;
157→      } catch (err) {
158→        // SSE not supported, use polling
159→        console.log("SSE not available, using polling");
160→        pollIntervalRef.current = setInterval(fetchStatus, pollIntervalMs);
161→      }
162→    };
163→
164→    connectSSE();
165→
166→    return () => {
167→      if (eventSourceRef.current) {
168→        eventSourceRef.current.close();
169→      }
170→      if (pollIntervalRef.current) {
171→        clearInterval(pollIntervalRef.current);
172→      }
173→    };
174→  }, [journeyId, enableSSE, pollIntervalMs, fetchStatus]);
175→
176→  // Initial fetch
177→  useEffect(() => {
178→    setIsLoading(true);
179→    fetchStatus().finally(() => setIsLoading(false));
180→  }, [fetchStatus]);
181→
182→  const refetch = useCallback(() => {
183→    setIsLoading(true);
184→    return fetchStatus().finally(() => setIsLoading(false));
185→  }, [fetchStatus]);
186→
187→  return {
188→    data,
189→    isLoading,
190→    error,
191→    isConnected,
192→    refetch,
193→  };
194→}
195→
196→/**
197→ * Hook for listing all active journeys.
198→ */
199→export function useActiveJourneys() {
200→  const [journeys, setJourneys] = useState<Array<{
201→    journey_id: string;
202→    phase: string;
203→    hypotheses_completed: number;
204→    total_hypotheses: number;
205→    state: string;
206→  }> | null>(null);
207→  const [isLoading, setIsLoading] = useState(false);
208→  const [error, setError] = useState<string | null>(null);
209→
210→  const fetchJourneys = useCallback(async () => {
211→    setIsLoading(true);
212→    try {
213→      const response = await fetch(`${API_BASE}/api/journey/active`);
214→      if (!response.ok) {
215→        throw new Error(`HTTP ${response.status}`);
216→      }
217→      const data = await response.json();
218→      setJourneys(data);
219→      setError(null);
220→    } catch (err) {
221→      setError(err instanceof Error ? err.message : "Unknown error");
222→    } finally {
223→      setIsLoading(false);
224→    }
225→  }, []);
226→
227→  useEffect(() => {
228→    fetchJourneys();
229→    const interval = setInterval(fetchJourneys, 30000); // Refresh every 30s
230→    return () => clearInterval(interval);
231→  }, [fetchJourneys]);
232→
233→  return { journeys, isLoading, error, refetch: fetchJourneys };
234→}
235→
236→/**
237→ * Hook for controlling a journey (pause/resume).
238→ */
239→export function useJourneyControl() {
240→  const [isLoading, setIsLoading] = useState(false);
241→  const [error, setError] = useState<string | null>(null);
242→
243→  const pauseJourney = async (journeyId: string) => {
244→    setIsLoading(true);
245→    try {
246→      const response = await fetch(`${API_BASE}/api/journey/pause/${journeyId}`, {
247→        method: "POST",
248→      });
249→      if (!response.ok) {
250→        throw new Error(`HTTP ${response.status}`);
251→      }
252→      const data = await response.json();
253→      setError(null);
254→      return data;
255→    } catch (err) {
256→      setError(err instanceof Error ? err.message : "Unknown error");
257→      throw err;
258→    } finally {
259→      setIsLoading(false);
260→    }
261→  };
262→
263→  const resumeJourney = async (journeyId: string) => {
264→    setIsLoading(true);
265→    try {
266→      const response = await fetch(`${API_BASE}/api/journey/resume/${journeyId}`, {
267→        method: "POST",
268→      });
269→      if (!response.ok) {
270→        throw new Error(`HTTP ${response.status}`);
271→      }
272→      const data = await response.json();
273→      setError(null);
274→      return data;
275→    } catch (err) {
276→      setError(err instanceof Error ? err.message : "Unknown error");
277→      throw err;
278→    } finally {
279→      setIsLoading(false);
280→    }
281→  };
282→
283→  return { pauseJourney, resumeJourney, isLoading, error };
284→}
