 58→export interface AlertEvent {
 59→  kind: string;
 60→  message: string;
 61→}
 62→
 63→export interface UniverseStreamState {
 64→  state: UniverseState | null;
 65→  report: SynthesisReport | null;
 66→  alerts: AlertEvent[];
 67→  connected: boolean;
 68→  error: string | null;
 69→}
 70→
 71→const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8080";
 72→const MAX_RECONNECT_DELAY = 30_000;
 73→
 74→/**
 75→ * SSE hook that streams live universe ticks from the Master Clock.
 76→ * Replaces polling — all Triune modes share one connection via UniverseProvider.
 77→ */
 78→export function useUniverseStream(): UniverseStreamState {
 79→  const [state, setState] = useState<UniverseState | null>(null);
 80→  const [report, setReport] = useState<SynthesisReport | null>(null);
 81→  const [alerts, setAlerts] = useState<AlertEvent[]>([]);
 82→  const [connected, setConnected] = useState(false);
 83→  const [error, setError] = useState<string | null>(null);
 84→  const esRef = useRef<EventSource | null>(null);
 85→  const retryRef = useRef(1000);
 86→
 87→  const connect = useCallback(() => {
 88→    esRef.current?.close();
 89→    const es = new EventSource(`${API_BASE}/api/universe/stream`);
 90→    esRef.current = es;
 91→
 92→    es.addEventListener("tick", (e: MessageEvent) => {
 93→      try {
 94→        setState(JSON.parse(e.data));
 95→        setConnected(true);
 96→        setError(null);
 97→        retryRef.current = 1000; // Reset backoff on success
 98→      } catch {
 99→        // Ignore malformed events
100→      }
101→    });
102→
103→    es.addEventListener("report", (e: MessageEvent) => {
104→      try {
105→        setReport(JSON.parse(e.data));
106→      } catch {
107→        // Ignore malformed events
108→      }
109→    });
110→
111→    es.addEventListener("alert", (e: MessageEvent) => {
112→      try {
113→        const alert: AlertEvent = JSON.parse(e.data);
114→        setAlerts((prev) => [...prev.slice(-49), alert]); // Keep last 50
115→      } catch {
116→        // Ignore malformed events
117→      }
118→    });
119→
120→    es.onerror = () => {
121→      setConnected(false);
122→      setError("Connection lost — reconnecting...");
123→      es.close();
124→      // Exponential backoff reconnect
125→      const delay = Math.min(retryRef.current, MAX_RECONNECT_DELAY);
126→      retryRef.current = delay * 2;
127→      setTimeout(connect, delay);
128→    };
129→  }, []);
130→
131→  useEffect(() => {
132→    connect();
133→    return () => {
134→      esRef.current?.close();
135→    };
136→  }, [connect]);
137→
138→  return { state, report, alerts, connected, error };
139→}
