19→export interface UniverseContextValue {
20→  /** Current tick state (null until first event). */
21→  state: UniverseState | null;
22→  /** Latest synthesis report (emitted every 10th tick). */
23→  report: SynthesisReport | null;
24→  /** Rolling alert buffer (last 50). */
25→  alerts: AlertEvent[];
26→  /** Whether the SSE stream is connected. */
27→  connected: boolean;
28→  /** Error message if disconnected. */
29→  error: string | null;
30→  /** Inject a perturbation into the universe. */
31→  perturb: (kind: string, magnitude?: number) => Promise<void>;
32→  /** Fetch a one-shot synthesis report. */
33→  fetchReport: () => Promise<SynthesisReport | null>;
34→}
35→
36→const UniverseContext = createContext<UniverseContextValue | null>(null);
37→
38→export function UniverseProvider({ children }: { children: ReactNode }) {
39→  const stream = useUniverseStream();
40→
41→  const perturb = useCallback(
42→    async (kind: string, magnitude = 0.2) => {
43→      try {
44→        await fetch(`${API_BASE}/api/universe/perturb`, {
45→          method: "POST",
46→          headers: { "Content-Type": "application/json" },
47→          body: JSON.stringify({ kind, magnitude }),
48→        });
49→      } catch {
50→        // Non-blocking — stream will show the result on next tick
51→      }
52→    },
53→    [],
54→  );
55→
56→  const fetchReport = useCallback(async (): Promise<SynthesisReport | null> => {
57→    try {
58→      const resp = await fetch(`${API_BASE}/api/universe/report`);
59→      if (!resp.ok) return null;
60→      return await resp.json();
61→    } catch {
62→      return null;
63→    }
64→  }, []);
65→
66→  return (
67→    <UniverseContext.Provider value={{ ...stream, perturb, fetchReport }}>
68→      {children}
69→    </UniverseContext.Provider>
70→  );
71→}
72→
73→/**
74→ * Access the shared universe state from any child of UniverseProvider.
75→ * Throws if used outside provider — intentional to catch wiring errors.
76→ */
77→export function useUniverse(): UniverseContextValue {
78→  const ctx = useContext(UniverseContext);
79→  if (!ctx) {
80→    throw new Error("useUniverse must be used within a UniverseProvider");
81→  }
82→  return ctx;
83→}
