 19→interface PointCloudProps {
 20→  points: number[][];
 21→  coherenceScores: number[];
 22→  highlightedIndex: number | null;
 23→  onPointClick: (index: number) => void;
 24→}
 25→
 26→function PointCloud({ points, coherenceScores, highlightedIndex, onPointClick }: PointCloudProps) {
 27→  const meshRef = useRef<THREE.Points>(null);
 28→
 29→  // Issue #11: Memoize geometry to prevent recreation on every render
 30→  const geometry = useMemo(() => {
 31→    const geom = new THREE.BufferGeometry();
 32→    const positions = new Float32Array(points.flat());
 33→    geom.setAttribute("position", new THREE.BufferAttribute(positions, 3));
 34→
 35→    // Color based on coherence (blue = low, green = medium, yellow/red = high)
 36→    const colors = new Float32Array(
 37→      points.flatMap((_, i) => {
 38→        const coherence = coherenceScores[i] ?? 0.5;
 39→        // Map coherence [0, 1] to color gradient: blue -> cyan -> green -> yellow -> red
 40→        const r = Math.min(1, Math.max(0, (coherence - 0.5) * 2));
 41→        const g = coherence > 0.5 ? 1 - (coherence - 0.5) * 2 : coherence * 2;
 42→        const b = Math.max(0, 1 - coherence * 2);
 43→        return [r, g, b];
 44→      })
 45→    );
 46→    geom.setAttribute("color", new THREE.BufferAttribute(colors, 3));
 47→    return geom;
 48→  }, [points, coherenceScores]);
 49→
 50→  // Animate rotation with velocity limit (Issue #20)
 51→  useFrame((state) => {
 52→    if (meshRef.current && highlightedIndex === null) {
 53→      const rotation = state.clock.elapsedTime * 0.1;
 54→      // Clamp rotation speed to prevent motion sickness
 55→      meshRef.current.rotation.y = rotation % (Math.PI * 2);
 56→    }
 57→  });
 58→
 59→  // Cleanup geometry on unmount
 60→  useEffect(() => {
 61→    return () => {
 62→      geometry.dispose();
 63→    };
 64→  }, [geometry]);
 65→
 66→  return (
 67→    <points ref={meshRef} geometry={geometry}>
 68→      <pointsMaterial
 69→        size={highlightedIndex !== null ? 0.03 : 0.05}
 70→        vertexColors
 71→        transparent
 72→        opacity={0.8}
 73→        sizeAttenuation
 74→      />
 75→    </points>
 76→  );
 77→}
